values
-- Civs
    -- America
    ("en_US",  "LOC_TRADITION_AMERICA_SYNCRETISM_ANTIQUITY_DESCRIPTION",   "[B]+1 [icon:YIELD_FOOD][/B] on [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resources[/TIP]."),
    ("en_US",  "LOC_TRADITION_AMERICA_SYNCRETISM_EXPLORATION_DESCRIPTION",   "[B]+1 [icon:YIELD_FOOD][/B] on [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resources[/TIP]. [B]+1 [icon:YIELD_PRODUCTION][/B] on Mines, Clay Pits, Quarries, Woodcutters, and Oil Rigs in [icon:TOWN_FOCUS] Mining [icon:YIELD_TOWNS] Towns, [icon:YIELD_WAREHOUSE] [TIP:LOC_PEDIA_CONCEPTS_WAREHOUSE_TOOLTIP]Warehouse[/TIP] Bonus."),
	-- Britain
    ("en_US", "LOC_TRAIT_GREAT_BRITAIN_ABILITY_MO_DESCRIPTION", "[BLIST][LI][B]+25% [icon:YIELD_GOLD] Gold[/B] towards purchasing [icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] and [B]+25% [icon:YIELD_PRODUCTION] Production[/B] towards constructing Buildings.[LI]It costs [B]50% more[/B] to convert [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP] into [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP].[LI][B]+2 [icon:YIELD_SCIENCE] Science[/B] on active Buildings adjacent to Coast.[LI][B]+30% [icon:YIELD_PRODUCTION] Production[/B] towards constructing Battersea Power Station.[/LIST]"),
    ("en_US",  "LOC_UNIT_REVENGE_BASE_DESCRIPTION",   "British Unique Heavy [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Unit[/TIP]. +3 [icon:NAR_REW_COMBAT] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat, Ranged, and Bombard Strength[/TIP]. Enemy Units in tiles adjacent to the target take 5% of the total damage done to the target."),
    ("en_US",  "LOC_UNIT_REVENGE_DESCRIPTION",   "Tier 2 British Unique Heavy [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Unit[/TIP]. +3 [icon:NAR_REW_COMBAT] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat, Ranged, and Bombard Strength[/TIP]. Enemy Units in tiles adjacent to the target take 5% of the total damage done to the target."),
    ("en_US",  "LOC_UNIT_REVENGE_2_DESCRIPTION",   "Tier 3 British Unique Heavy [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Unit[/TIP]. +3 [icon:NAR_REW_COMBAT] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat, Ranged, and Bombard Strength[/TIP]. Enemy Units in tiles adjacent to the target take 5% of the total damage done to the target."),
    --France
    ("en_US",  "LOC_TRADITION_STYLE_EMPIRE_I_DESCRIPTION",   "Constructing a [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Building[/TIP] grants [icon:YIELD_CULTURE] equal to 25% of its [icon:YIELD_PRODUCTION] cost. [B]+2 [icon:YIELD_CULTURE][/B] on Happiness Buildings and [icon:WONDER] [TIP:LOC_PEDIA_CONCEPTS_WONDERS_TOOLTIP]Wonders[/TIP]."),
    ("en_US",  "LOC_TRADITION_STYLE_EMPIRE_II_DESCRIPTION",   "Constructing a [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Building[/TIP] grants [icon:YIELD_CULTURE] equal to 50% of its [icon:YIELD_PRODUCTION] cost. [B]+2 [icon:YIELD_CULTURE][/B] on Happiness Buildings and [icon:WONDER] [TIP:LOC_PEDIA_CONCEPTS_WONDERS_TOOLTIP]Wonders[/TIP]."),
    ("en_US",  "LOC_TRADITION_COCORICO_I_DESCRIPTION",   "When you defeat an enemy Unit, gain [icon:YIELD_CULTURE] equal to 25% of its [icon:NAR_REW_COMBAT] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP]. [B]+2 [icon:YIELD_HAPPINESS][/B] on [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Military Buildings[/TIP] and [icon:WONDER] [TIP:LOC_PEDIA_CONCEPTS_WONDERS_TOOLTIP]Wonders[/TIP]."),
    ("en_US",  "LOC_TRADITION_COCORICO_II_DESCRIPTION",   "When you defeat an enemy Unit, gain [icon:YIELD_CULTURE] equal to 50% of its [icon:NAR_REW_COMBAT] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP]. [B]+2 [icon:YIELD_HAPPINESS][/B] on [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Military Buildings[/TIP] and [icon:WONDER] [TIP:LOC_PEDIA_CONCEPTS_WONDERS_TOOLTIP]Wonders[/TIP]."),
    
    ("en_US",  "LOC_TRAIT_RUSSIA_ABILITY_EX_DESCRIPTION",   "[BLIST][LI][B]+1 [icon:YIELD_CULTURE] Culture on [icon:CITY_UNIQUE_QUARTER] [TIP:LOC_PEDIA_CONCEPTS_DISTRICT_TOOLTIP]Quarters[/TIP][/B] in [B][icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP][/B]. [B]+1 [icon:YIELD_SCIENCE] Science on [icon:CITY_UNIQUE_QUARTER] Quarters[/B] in [B][icon:YIELD_CITIES] Cities[/B] in [B]Tundra[/B].[LI][B]+1 [icon:YIELD_FOOD] Food on Farms[/B]. [B]+1 [icon:YIELD_PRODUCTION] Production on Farms[/B] in [B]Tundra[/B], count as [icon:YIELD_WAREHOUSE] Warehouse Bonus.[/BLIST]"),
    ("en_US",  "LOC_TRAIT_RUSSIA_ABILITY_AQ_DESCRIPTION",   "[BLIST][LI][B]+1 [icon:YIELD_CULTURE] Culture on [icon:CITY_UNIQUE_QUARTER] [TIP:LOC_PEDIA_CONCEPTS_DISTRICT_TOOLTIP]Quarters[/TIP][/B] in [B][icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP][/B]. [B]+1 [icon:YIELD_SCIENCE] Science on [icon:CITY_UNIQUE_QUARTER] Quarters[/B] in [B][icon:YIELD_CITIES] Cities[/B] in [B]Tundra[/B].[LI][B]+1 [icon:YIELD_FOOD] Food on Farms[/B]. [B]+1 [icon:YIELD_PRODUCTION] Production on Farms[/B] in [B]Tundra[/B], count as [icon:YIELD_WAREHOUSE] Warehouse Bonus.[/BLIST]"),
    ("en_US",  "LOC_TRAIT_RUSSIA_ABILITY_DESCRIPTION",   "[BLIST][LI][B]+1 [icon:YIELD_CULTURE] Culture on [icon:CITY_UNIQUE_QUARTER] [TIP:LOC_PEDIA_CONCEPTS_DISTRICT_TOOLTIP]Quarters[/TIP][/B] in [B][icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP][/B]. [B]+1 [icon:YIELD_SCIENCE] Science on [icon:CITY_UNIQUE_QUARTER] Quarters[/B] in [B][icon:YIELD_CITIES] Cities[/B] in [B]Tundra[/B].[LI][B]+1 [icon:YIELD_FOOD] Food on Farms[/B]. [B]+1 [icon:YIELD_PRODUCTION] Production on Farms[/B] in [B]Tundra[/B], count as [icon:YIELD_WAREHOUSE] Warehouse Bonus.[LI][B]+30% [icon:YIELD_PRODUCTION] Production[/B] towards constructing the [B]Hermitage[/B].[/BLIST]"),
    -- Meji Japan
    ('en_US', 'LOC_TRAIT_MEIJI_ABILITY_AQ_DESCRIPTION', '[BLIST][LI]When you construct a [icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Building[/TIP], gain [icon:YIELD_SCIENCE] Science equal to 25% of the Building''s [icon:YIELD_PRODUCTION] Production cost.[/BLIST]'),
    ('en_US', 'LOC_TRAIT_MEIJI_ABILITY_EX_DESCRIPTION', '[BLIST][LI]When you construct a [icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Building[/TIP], gain [icon:YIELD_SCIENCE] Science equal to 25% of the Building''s [icon:YIELD_PRODUCTION] Production cost.[/BLIST]'),
    ('en_US', 'LOC_TRAIT_MEIJI_ABILITY_DESCRIPTION', '[BLIST][LI]When you construct a [icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Building[/TIP], gain [icon:YIELD_SCIENCE] Science equal to 25% of the Building''s [icon:YIELD_PRODUCTION] Production cost.[LI]+30% [icon:YIELD_PRODUCTION] Production towards constructing Dogo Onsen.[/BLIST]'),
    ('en_US', 'LOC_TRADITION_SHUSEI_KOKUBO_I_DESCRIPTION', '[B]+50% [icon:YIELD_PRODUCTION][/B] towards Military, Science, and Production Buildings.'),
    ('en_US', 'LOC_TRADITION_SHUSEI_KOKUBO_II_DESCRIPTION', '[B]+50% [icon:YIELD_PRODUCTION][/B] towards Military, Science, and Production Buildings. Military, Science, and Production Buildings receive an adjacency for Coast.'),
    ('en_US', 'LOC_TRADITION_O_YATOI_GAIKOKUJIN_I_DESCRIPTION', '[B]+1 [icon:YIELD_PRODUCTION][/B] and [icon:YIELD_SCIENCE] from [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_TOOLTIP]Specialists[/TIP] in all Settlements.'),
    ('en_US', 'LOC_TRADITION_O_YATOI_GAIKOKUJIN_II_DESCRIPTION', '[B]+2 [icon:YIELD_PRODUCTION][/B] and [icon:YIELD_SCIENCE] from [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_TOOLTIP]Specialists[/TIP] in all Settlements.'),
    ('en_US', 'LOC_TRADITION_MEIJI_SYNCRETISM_ANTIQUITY_DESCRIPTION', '[B]+1 [icon:YIELD_SCIENCE][/B] for every [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_EMPIRE_RESOURCES_TOOLTIP]Empire Resource[/TIP]. [B]+1 [icon:YIELD_SCIENCE][/B] in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] adjacent to Coast for every [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resource[/TIP] assigned to them.'),
    ('en_US', 'LOC_TRADITION_MEIJI_SYNCRETISM_EXPLORATION_DESCRIPTION', '[B]+2 [icon:YIELD_SCIENCE][/B] for every [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_EMPIRE_RESOURCES_TOOLTIP]Empire Resource[/TIP]. [B]+2 [icon:YIELD_SCIENCE][/B] in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] adjacent to Coast for every [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resource[/TIP] assigned to them.'),
    -- Joseon
    ("en_US", "LOC_BUILDING_CONFUCIAN_ACADEMY_DESCRIPTION", "Joseon [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_BUILDING_TOOLTIP]Unique Culture Building[/TIP]. +9 [icon:YIELD_CULTURE] Culture. +1 [icon:YIELD_HAPPINESS] Happiness Adjacency for [icon:CITY_UNIMPROVED] Mountains and [icon:WONDER] [TIP:LOC_PEDIA_CONCEPTS_WONDERS_TOOLTIP]Wonders[/TIP]. Can be purchased in [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP]."),
    ("en_US", "LOC_BUILDING_CONFUCIAN_ACADEMY_TOOLTIP", "Joseon [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_BUILDING_TOOLTIP]Unique Building[/TIP]. Can be built in the [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP] or purchased in [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP]."),
    ("en_US", "LOC_BUILDING_PRINTING_HOUSE_DESCRIPTION", "Joseon [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_BUILDING_TOOLTIP]Unique Science Building[/TIP]. +9 [icon:YIELD_SCIENCE] Science. +1 [icon:YIELD_PRODUCTION] Production Adjacency for [icon:CITY_UNIQUE_QUARTER] [TIP:LOC_PEDIA_CONCEPTS_QUARTERS_TOOLTIP]Quarters[/TIP] and [icon:WONDER] [TIP:LOC_PEDIA_CONCEPTS_WONDERS_TOOLTIP]Wonders[/TIP]. Can be purchased in [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP]."),
    ("en_US", "LOC_BUILDING_PRINTING_HOUSE_TOOLTIP", "Joseon [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_BUILDING_TOOLTIP]Unique Building[/TIP]. Can be built in the [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP] or purchased in [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP]."),
    ("en_US", "LOC_CIVILIZATION_JOSEON_DESCRIPTION", "[B]+2[/B] [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_LIMIT_TOOLTIP]Specialist Limit[/TIP] in the [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP]. Other [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] receive +1 [icon:SPECIALIST] Specialist Limit if they have a [icon:CITY_UNIQUE_QUARTER] Seowon. [BLIST][LI][icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP] can purchase Tier 1 Culture and Science [icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] with any Town Focus.[LI][B]Antiquity:[/B] Initial City Limit 1; +1 at Joseon Origins and Joseon Foundation. [B]Exploration:[/B] Initial City Limit 3; +1 at Joseon Renaissance. [B]Modern:[/B] Initial City Limit 4; +1 at Ihak, Seonbi, and Samgang.[LI][B]+30% [icon:YIELD_PRODUCTION] Production[/B] towards constructing Hwaseong.[/LIST]"),
    ("en_US", "LOC_TRAIT_JOSEON_ABILITY_AQ_DESCRIPTION", "[BLIST][LI][B]+1 [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_LIMIT_TOOLTIP]Specialist Limit[/TIP][/B] in the [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP].[LI][B]Initial City Limit: 1.[/B] Gain [B]+1 City Limit[/B] at Joseon Origins and another [B]+1[/B] at Joseon Foundation.[LI][icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP] can purchase Tier 1 [icon:YIELD_CULTURE] Culture and [icon:YIELD_SCIENCE] Science [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] with any Town Focus.[/LIST]"),
    ("en_US", "LOC_TRAIT_JOSEON_ABILITY_EX_DESCRIPTION", "[BLIST][LI][B]+2 [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_LIMIT_TOOLTIP]Specialist Limit[/TIP][/B] in the [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP].[LI][B]Initial City Limit: 3.[/B] Gain [B]+1 City Limit[/B] at Joseon Renaissance.[LI][icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP] can purchase Tier 1 [icon:YIELD_CULTURE] Culture and [icon:YIELD_SCIENCE] Science [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] with any Town Focus.[/LIST]"),
    ("en_US", "LOC_TRAIT_JOSEON_ABILITY_MO_DESCRIPTION", "[BLIST][LI][B]+2 [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_LIMIT_TOOLTIP]Specialist Limit[/TIP][/B] in the [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP].[LI]Other [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] receive [B]+1 [icon:SPECIALIST] Specialist Limit[/B] with a [icon:CITY_UNIQUE_QUARTER] Seowon.[LI][B]Initial City Limit: 4.[/B] Gain [B]+1 City Limit[/B] at Ihak, Seonbi, and Samgang.[LI][icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP] can purchase Tier 1 [icon:YIELD_CULTURE] Culture and [icon:YIELD_SCIENCE] Science [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] with any Town Focus.[LI][B]+30% [icon:YIELD_PRODUCTION] Production[/B] towards constructing Hwaseong.[/LIST]"),
    ("en_US", "LOC_TRADITION_GWAGEO_I_DESCRIPTION", "[B]+2 [icon:YIELD_CULTURE][/B] from [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_TOOLTIP]Specialists[/TIP]. But [B]-0.5 [icon:YIELD_HAPPINESS][/B] on [icon:SPECIALIST] Specialists."),
    ("en_US", "LOC_TRADITION_GWAGEO_DESCRIPTION", "[B]+3 [icon:YIELD_CULTURE][/B] from [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_TOOLTIP]Specialists[/TIP]."),
    ("en_US", "LOC_TRADITION_SILHAK_DESCRIPTION", "[B]+3 [icon:YIELD_SCIENCE][/B] from [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_TOOLTIP]Specialists[/TIP]."),
    ("en_US", "LOC_TRADITION_JOSEON_SYNCRETISM_ANTIQUITY_DESCRIPTION", "[B]+0.5 [icon:YIELD_HAPPINESS][/B] per [icon:YIELD_POPULATION] [TIP:LOC_PEDIA_CONCEPTS_POPULATION_TOOLTIP]Population[/TIP] in all [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP]."),
    ("en_US", "LOC_TRADITION_JOSEON_SYNCRETISM_EXPLORATION_DESCRIPTION", "[B]+1 [icon:YIELD_HAPPINESS][/B] per [icon:YIELD_POPULATION] [TIP:LOC_PEDIA_CONCEPTS_POPULATION_TOOLTIP]Population[/TIP] in all [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP]."),
    ("en_US", "LOC_TRADITION_YANGBAN_BUREAUCRACY_I_DESCRIPTION", "[icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] receive [B]+1 [icon:YIELD_FOOD] Food[/B] and [B]+1 [icon:YIELD_PRODUCTION] Production[/B] on [icon:CITY_URBAN] [TIP:LOC_PEDIA_CONCEPTS_DISTRICT_TOOLTIP]Districts[/TIP] per assigned [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_TOOLTIP]Specialist[/TIP], up to [B]2[/B]."),
    ("en_US", "LOC_TRADITION_YANGBAN_BUREAUCRACY_DESCRIPTION", "[icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] receive [B]+1 [icon:YIELD_FOOD] Food[/B] and [B]+1 [icon:YIELD_PRODUCTION] Production[/B] on [icon:CITY_URBAN] [TIP:LOC_PEDIA_CONCEPTS_DISTRICT_TOOLTIP]Districts[/TIP] per assigned [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_TOOLTIP]Specialist[/TIP], up to [B]4[/B]."),
    ("en_US", "LOC_TRADITION_YANGBEOBMIUI_DESCRIPTION", "[B]+0.5 [icon:YIELD_CULTURE][/B] per [icon:YIELD_POPULATION] [TIP:LOC_PEDIA_CONCEPTS_POPULATION_TOOLTIP]Population[/TIP] in the [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP] and [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] with a Seowon. [B]+15% [icon:YIELD_FOOD][/B] in [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP] with any Focus."),
    ("en_US",  "LOC_QUARTER_SEOWON_DESCRIPTION",   "Joseon [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_QUARTER_TOOLTIP]Unique Quarter[/TIP]. Created by constructing the Confucian Academy and Printing House in the same [TIP:LOC_PEDIA_CONCEPTS_DISTRICT_TOOLTIP]District[/TIP]. This [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlement[/TIP] receives +25% of its [icon:YIELD_PRODUCTION] Production as [icon:YIELD_CULTURE] Culture. If constructed in a [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Town[/TIP] the [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP] receives +1 [icon:YIELD_POPULATION] [TIP:LOC_PEDIA_CONCEPTS_POPULATION_TOOLTIP]Population[/TIP]."),
    ("en_US",  "LOC_QUARTER_SEOWON_TOOLTIP",   "This [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlement[/TIP] receives +25% of its [icon:YIELD_PRODUCTION] Production as [icon:YIELD_CULTURE] Culture. If constructed in a [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Town[/TIP] the [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP] receives +1 [icon:YIELD_POPULATION] [TIP:LOC_PEDIA_CONCEPTS_POPULATION_TOOLTIP]Population[/TIP]."),
    -- Mexico
    ("en_US",  "LOC_TRADITION_CRY_OF_DOLORES_DESCRIPTION",   "[B]+1 [icon:NAR_REW_COMBAT][/B] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP] for [TIP:LOC_PEDIA_CONCEPTS_LAND_UNITS_TOOLTIP]Land Units[/TIP] and [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Units[/TIP] in friendly territory for every [icon:TRADITION] [TIP:LOC_PEDIA_CONCEPTS_TRADITION_TOOLTIP]Tradition[/TIP] slotted into the [icon:GOVERNMENT] [TIP:LOC_PEDIA_CONCEPTS_GOVERNMENT_TOOLTIP]Government[/TIP], up to [B]+4[/B]."),
    -- Mughal
    ("en_US", "LOC_CIVILIZATION_MUGHAL_DESCRIPTION", "+75% [icon:YIELD_GOLD] Gold yields. -25% to all other yields."),
    ("en_US", "LOC_TRAIT_MUGHAL_ABILITY_AQ_DESCRIPTION", "[BLIST][LI][B]+75% [icon:YIELD_GOLD] Gold[/B] yields.[LI][B]-25%[/B] to [B]all other[/B] yields [B]except [icon:YIELD_FOOD] Food[/B].[LI]You can purchase [B][icon:WONDER] [TIP:LOC_PEDIA_CONCEPTS_WONDERS_TOOLTIP]Wonders[/TIP][/B] with [B][icon:YIELD_GOLD] Gold[/B], but they are [B]150%[/B] more expensive.[/LIST]"),
    -- Ottomans
    ("en_US",  "LOC_UNIT_JANISSARY_BASE_DESCRIPTION",   "Ottoman [TIP:LOC_PEDIA_CONCEPTS_INFANTRY_UNITS_TOOLTIP]Infantry[/TIP] replacement. +3 [icon:NAR_REW_COMBAT] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP] against other [TIP:LOC_PEDIA_CONCEPTS_LAND_UNITS_TOOLTIP]Land Units[/TIP]. All Civilizations’ [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] suffer a -2 [icon:YIELD_HAPPINESS] Happiness penalty for every Janissary [TIP:LOC_PEDIA_CONCEPTS_STATIONED_TOOLTIP]stationed[/TIP] in or occupying a [icon:CITY_URBAN] [TIP:LOC_PEDIA_CONCEPTS_DISTRICT_TOOLTIP]District[/TIP]."),
