    ("en_US",  "LOC_WONDER_STATUE_OF_LIBERTY_DESCRIPTION",   "+6 [icon:YIELD_HAPPINESS] Happiness. Spawns 4 [icon:UNIT_MIGRANT] Migrants. [TIP:LOC_PEDIA_CONCEPTS_AGELESS_TOOLTIP]Ageless[/TIP]. Must be placed on Coast adjacent to land. [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_TOOLTIP]Specialists[/TIP] recieve +1 [icon:YIELD_DIPLOMACY] Influence."),
    ("en_US",  "LOC_WONDER_STATUE_OF_LIBERTY_TOOLTIP",   "Spawns 4 [icon:UNIT_MIGRANT] Migrants.[icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_TOOLTIP]Specialists[/TIP] recieve +1 [icon:YIELD_DIPLOMACY] Influence.[n]Must be placed on Coast adjacent to land."),
    -- Boudhanath
    ("en_US",  "LOC_WONDER_BOUDHANATH_DESCRIPTION",   "+6 [icon:YIELD_DIPLOMACY] Influence. +50 [icon:RELATIONSHIP] Relationship with all other Leaders. [TIP:LOC_PEDIA_CONCEPTS_AGELESS_TOOLTIP]Ageless[/TIP]. Must be built in Grassland or Tropical adjacent to a Mountain."),
    ("en_US",  "LOC_WONDER_BOUDHANATH_TOOLTIP",   "+50 [icon:RELATIONSHIP] Relationship with all other Leaders.[N]Must be built in Grassland or Tropical adjacent to a Mountain."),
    -- Eram Garden
    ("en_US",  "LOC_WONDER_ERAM_GARDEN_DESCRIPTION",   "+4 [icon:YIELD_FOOD] Food. +1 [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_LIMIT_TOOLTIP]Specialist Limit[/TIP] and [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_TOOLTIP]Specialists[/TIP] recieve +2 [icon:YIELD_CULTURE] Culture and [icon:YIELD_HAPPINESS] Happiness in this [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlement[/TIP]. [TIP:LOC_PEDIA_CONCEPTS_AGELESS_TOOLTIP]Ageless[/TIP]. Must be built in Desert Terrain."),
    ("en_US",  "LOC_WONDER_ERAM_GARDEN_TOOLTIP",   "+1 [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_LIMIT_TOOLTIP]Specialist Limit[/TIP] and [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_TOOLTIP]Specialists[/TIP] recieve +2 [icon:YIELD_CULTURE] Culture and [icon:YIELD_HAPPINESS] Happiness in this [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlement[/TIP].[N]Must be built in Desert Terrain."),
    -- Nirayama Reverberatory Furnace
    ("en_US",  "LOC_WONDER_NIRAYAMA_REVERBERATORY_FURNACE_DESCRIPTION",   "+4 [icon:YIELD_HAPPINESS] Happiness. +4 [icon:YIELD_PRODUCTION] Production on Mines on [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resources[/TIP] in this [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlement[/TIP]. +1 [icon:YIELD_SCIENCE] Science on all Mines. [TIP:LOC_PEDIA_CONCEPTS_AGELESS_TOOLTIP]Ageless[/TIP]. Must be placed adjacent to a Mine on a Resource."),
    ("en_US",  "LOC_WONDER_NIRAYAMA_REVERBERATORY_FURNACE_TOOLTIP",   "+4 [icon:YIELD_PRODUCTION] Production on Mines on [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resources[/TIP] in this [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlement[/TIP]. +1 [icon:YIELD_SCIENCE] Science on all Mines.[N]Must be placed adjacent to a Mine on a Resource."),
    -- Hermitage
    ("en_US",  "LOC_WONDER_HERMITAGE_DESCRIPTION",   "+4 [icon:YIELD_CULTURE] Culture. +5 [icon:YIELD_CULTURE] Culture in [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] that have a [icon:NAR_REW_GREATWORK] [TIP:LOC_PEDIA_CONCEPTS_GREAT_WORKS_TOOLTIP]Great Work[/TIP] on display. +3 [icon:CULTURE_VP] Tourism from Artifact. Has 3 [TIP:LOC_PEDIA_CONCEPTS_GREAT_WORKS_TOOLTIP]Great Work[/TIP] slots. [TIP:LOC_PEDIA_CONCEPTS_AGELESS_TOOLTIP]Ageless[/TIP]. Must be placed on Tundra."),
    ("en_US",  "LOC_WONDER_HERMITAGE_TOOLTIP",   "+5 [icon:YIELD_CULTURE] Culture in [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] that have a [icon:NAR_REW_GREATWORK] [TIP:LOC_PEDIA_CONCEPTS_GREAT_WORKS_TOOLTIP]Great Work[/TIP] on display. +3 [icon:CULTURE_VP] Tourism from Artifact. Has 3 [TIP:LOC_PEDIA_CONCEPTS_GREAT_WORKS_TOOLTIP]Great Work[/TIP] slots.[n]Must be placed on Tundra."),


-- Government changes
    ("en_US", "LOC_GOVERNMENT_AUTHORITARIANISM_PASSIVE_DESCRIPTION", "+5 [icon:YIELD_FOOD] Food and [icon:YIELD_GOLD] Gold in Settlements you have conquered in any Age. Unhappiness causes a smaller reduction in Settlement yields per point of negative [icon:YIELD_HAPPINESS] Happiness."),
    ("en_US", "LOC_GOLDEN_AGE_AUTHORITARIANISM_1_DESCRIPTION", "+25% [icon:YIELD_PRODUCTION] Production towards training Military Units and constructing Walls for {1_numTurns} Turn(s)."),
    ("en_US", "LOC_GOLDEN_AGE_AUTHORITARIANISM_2_DESCRIPTION", "Gain +1 Settlement Limit."),
    ("en_US", "LOC_GOLDEN_AGE_BUREAUCRATIC_MONARCHY_1_DESCRIPTION", "+1000 [icon:YIELD_GOLD] Gold immediately (scales by Game Speed)."),
    ("en_US", "LOC_GOLDEN_AGE_BUREAUCRATIC_MONARCHY_2_DESCRIPTION", "+40% [icon:YIELD_DIPLOMACY] Influence towards initiating all Diplomatic Actions for {1_numTurns} Turn(s)."),
    ("en_US", "LOC_TRADITION_EVIDENZBUREAU_DESCRIPTION", "[B]+50% [icon:YIELD_DIPLOMACY] Influence[/B] towards initiating [icon:ESPIONAGE] [TIP:LOC_PEDIA_CONCEPTS_ESPIONAGE_TOOLTIP]Espionage Actions[/TIP], which complete 25% faster."),
    ("en_US", "LOC_GOVERNMENT_ELECTIVE_REPUBLIC_PASSIVE_DESCRIPTION", "[icon:SPECIALIST] Specialists get +1 [icon:YIELD_SCIENCE] Science and [icon:YIELD_CULTURE] Culture."),

-- City-State balance changes
    ("en_US", "LOC_IMPROVEMENT_OPEN_AIR_MUSEUM_DESCRIPTION", "Cultural City-State [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_IMPROVEMENT_TOOLTIP]Unique Improvement[/TIP]. +5 [icon:YIELD_CULTURE] Culture. +2 [icon:YIELD_SCIENCE] Science for each adjacent Tropical terrain, +2 [icon:YIELD_CULTURE] Culture for each adjacent Tundra terrain, +2 [icon:YIELD_GOLD] Gold for each adjacent Desert terrain, and +1 [icon:YIELD_PRODUCTION] Production for each adjacent Grassland or Plains tile. [TIP:LOC_PEDIA_CONCEPTS_AGELESS_TOOLTIP]Ageless[/TIP]. One Per [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlement[/TIP]."),
    ("en_US", "LOC_IMPROVEMENT_OPEN_AIR_MUSEUM_TOOLTIP", "+1 [icon:YIELD_PRODUCTION] Production for each adjacent Grassland or Plains tile.[n]Does not remove [icon:YIELD_WAREHOUSE] [TIP:LOC_PEDIA_CONCEPTS_WAREHOUSE_TOOLTIP]Warehouse[/TIP] bonuses on a tile. One Per [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlement[/TIP].[n]City-State [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_IMPROVEMENT_TOOLTIP]Unique Improvement[/TIP]."),
    ("en_US", "LOC_CITY_STATE_BONUS_MODERN_6_DESCRIPTION", "Allows the construction of the Open-Air Museum Unique Improvement. [n]The Open-Air Museum provides +5 [icon:YIELD_CULTURE] Culture; +2 [icon:YIELD_SCIENCE] Science for each adjacent Tropical tile; +2 [icon:YIELD_CULTURE] Culture for each adjacent Tundra tile; +2 [icon:YIELD_GOLD] Gold for each adjacent Desert tile; and +1 [icon:YIELD_PRODUCTION] Production for each adjacent Grassland or Plains tile. One per Settlement."),
    ("en_US", "LOC_IMPROVEMENT_ABATTOIR_DESCRIPTION", "Expansionist City-State [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_IMPROVEMENT_TOOLTIP]Unique Improvement[/TIP]. +5 [icon:YIELD_FOOD] Food. +1 [icon:YIELD_PRODUCTION] Production on each Abattoir in this [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlement[/TIP]. [TIP:LOC_PEDIA_CONCEPTS_AGELESS_TOOLTIP]Ageless[/TIP]. Must be placed with a [icon:YIELD_FOOD] Food yield, and cannot be adjacent to another Abattoir."),
    ("en_US", "LOC_IMPROVEMENT_ABATTOIR_TOOLTIP", "Effect: +1 [icon:YIELD_PRODUCTION] Production on each Abattoir in this [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlement[/TIP].[n]Does not remove [icon:YIELD_WAREHOUSE] [TIP:LOC_PEDIA_CONCEPTS_WAREHOUSE_TOOLTIP]Warehouse[/TIP] bonuses on a tile. Must be placed with a [icon:YIELD_FOOD] Food yield, and cannot be adjacent to another Abattoir.[n]City-State [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_IMPROVEMENT_TOOLTIP]Unique Improvement[/TIP]."),
    ("en_US", "CITY_STATE_EXPANSIONIST_BONUS_MODERN_1_DESCRIPTION", "Allows the construction of the Abattoir Unique Improvement. [n]The Abattoir provides +5 [icon:YIELD_FOOD] Food and +1 [icon:YIELD_PRODUCTION] Production on each Abattoir in its Settlement. Must be placed on an existing Improvement on a tile with a [icon:YIELD_FOOD] Food yield. Cannot be placed adjacent to another Abattoir.");
